import assert from 'node:assert/strict';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import {spawnSync} from 'node:child_process';
import {EdgeDatabaseService} from '../tridentpos/packages/edge/dist/index.js';
import {SqliteCashShiftRepository} from '../tridentpos/packages/pos-edge-runtime/dist/index.js';
const dir=fs.mkdtempSync(path.join(os.tmpdir(),'rebind65-'));const file=path.join(dir,'db');
const db=new EdgeDatabaseService({databasePath:file});const repo=new SqliteCashShiftRepository(db);
const shift={id:'S',organizationId:'ORG',branchId:'BR',stationId:'ST',responsibleUserId:'OP',openedByUserId:'OP',shiftNumber:1,openingCashFloat:10000n,closingDeclaredCash:9999n,calculatedCashTotal:10000n,cashDifference:-1n,status:'CERRADO_ARQUEO',assignmentStrategy:'COMPARTIDO',participatingOperators:['OP'],openedAt:new Date().toISOString(),closedAt:null,version:2,updatedAt:new Date().toISOString()};repo.saveShiftSync(shift,0);db.close();
const edge=path.resolve('tridentpos/packages/edge/dist/index.js');const runtime=path.resolve('tridentpos/packages/pos-edge-runtime/dist/index.js');
const childCode=`import {EdgeDatabaseService} from ${JSON.stringify(edge)};import {SqliteCashShiftRepository} from ${JSON.stringify(runtime)};const db=new EdgeDatabaseService({databasePath:process.argv[1]});const repo=new SqliteCashShiftRepository(db,{onBeforeCorteZCommit:()=>{const full=db.queryRowSafe('PRAGMA synchronous;');console.log(JSON.stringify({insideTransactionSynchronous:full},(_,v)=>typeof v==='bigint'?v.toString():v));process.kill(process.pid,'SIGKILL');}});const s=repo.getShiftByIdSync('S');const c={id:'C',turnoCajaId:'S',tipoCorte:'CORTE_Z',generatedByUserId:'OP',openingCashFloat:10000n,totalIngresos:0n,totalEgresos:0n,totalVentasEfectivo:0n,totalCalculado:10000n,totalDeclarado:9999n,diferencia:-1n,desgloseOperadores:[],generatedAt:new Date().toISOString()};repo.saveCorteZSync(c,{...s,status:'CORTE_Z_EMITIDO',closedAt:new Date().toISOString(),version:3},2);`;
const child=spawnSync(process.execPath,['--input-type=module','-e',childCode,file],{encoding:'utf8'});assert.equal(child.signal,'SIGKILL',child.stderr);console.log(child.stdout.trim());
const recovered=new EdgeDatabaseService({databasePath:file});const rr=new SqliteCashShiftRepository(recovered);assert.equal(rr.getShiftByIdSync('S').version,2);
const counts=()=>['cortes_caja','local_audit_trail','outbox_queue'].map(t=>recovered.queryRowsSafe(`SELECT * FROM ${t}`).length);assert.deepEqual(counts(),[0,0,0]);console.log(JSON.stringify({crashSignal:child.signal,shiftVersion:2,counts:counts()}));
const c={id:'C',turnoCajaId:'S',tipoCorte:'CORTE_Z',generatedByUserId:'OP',openingCashFloat:10000n,totalIngresos:0n,totalEgresos:0n,totalVentasEfectivo:0n,totalCalculado:10000n,totalDeclarado:9999n,diferencia:-1n,desgloseOperadores:[],generatedAt:new Date().toISOString()};rr.saveCorteZSync(c,{...shift,status:'CORTE_Z_EMITIDO',closedAt:new Date().toISOString(),version:3},2);assert.deepEqual(counts(),[1,1,1]);recovered.close();
const finalDb=new EdgeDatabaseService({databasePath:file});assert.deepEqual(['cortes_caja','local_audit_trail','outbox_queue'].map(t=>finalDb.queryRowsSafe(`SELECT * FROM ${t}`).length),[1,1,1]);console.log(JSON.stringify({committedReopenCounts:[1,1,1],moneyDifference:finalDb.queryRowsSafe('SELECT cash_difference FROM turnos_caja').map(r=>String(r.cash_difference))}));finalDb.close();fs.rmSync(dir,{recursive:true,force:true});

